instruction:
Refactor this code by applying the Strategy pattern to the format branching:

def export(rows, fmt):
    if fmt == 'csv':
        out = ','.join(rows[0].keys()) + '\n'
        for r in rows:
            out += ','.join(str(v) for v in r.values()) + '\n'
        return out
    elif fmt == 'json':
        return json.dumps(rows)
    elif fmt == 'tsv':
        out = '\t'.join(rows[0].keys()) + '\n'
        for r in rows:
            out += '\t'.join(str(v) for v in r.values()) + '\n'
        return out
    raise ValueError(fmt)

output:
from abc import ABC, abstractmethod

class Exporter(ABC):
    @abstractmethod
    def export(self, rows) -> str: ...

class CSVExporter(Exporter):
    sep = ','
    def export(self, rows):
        lines = [self.sep.join(rows[0].keys())]
        lines += [self.sep.join(str(v) for v in r.values()) for r in rows]
        return '\n'.join(lines) + '\n'

class TSVExporter(CSVExporter):
    sep = '\t'

class JSONExporter(Exporter):
    def export(self, rows):
        return json.dumps(rows)

EXPORTERS = {'csv': CSVExporter(), 'json': JSONExporter(), 'tsv': TSVExporter()}

def export(rows, fmt):
    return EXPORTERS[fmt].export(rows)

What changed: each format is a Strategy object selected from a registry; adding XML means adding one class, not another elif.

