def make_connection(cfg):
    if cfg['type'] == 'postgres':
        c = PsycopgConnection(cfg['dsn'])
        c.autocommit = False
        return c
    elif cfg['type'] == 'sqlite':
        c = SqliteConnection(cfg['path'])
        c.isolation_level = None
        return c
    elif cfg['type'] == 'memory':
        return SqliteConnection(':memory:')
    raise ValueError('unknown type')

output:
class ConnectionFactory:
    _builders = {
        'postgres': lambda cfg: PsycopgConnection(cfg['dsn'], autocommit=False),
        'sqlite': lambda cfg: SqliteConnection(cfg['path'], isolation_level=None),
        'memory': lambda cfg: SqliteConnection(':memory:'),
    }
    @classmethod
    def create(cls, cfg):
        try:
            builder = cls._builders[cfg['type']]
        except KeyError:
            raise ValueError(f'unknown type: {cfg["type"]}') from None
        return builder(cfg)

def make_connection(cfg):
    return ConnectionFactory.create(cfg)

What changed: construction knowledge moved into a factory registry; per-type setup flags no longer live in a conditional ladder.

