output:
class Store:
    def __init__(self):
        self.items = []
        self._observers = []
    def subscribe(self, fn):
        self._observers.append(fn)
        return lambda: self._observers.remove(fn)
    def add(self, item):
        self.items.append(item)
        for fn in tuple(self._observers):
            fn(item)

store = Store()
store.subscribe(update_ui)
store.subscribe(write_audit_log)

What changed: fixed on_add_* slots became a subscriber list; new listeners register without editing Store, and unsubscribe returns a handle.

from functools import wraps
import time

def audited(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not request.headers.get('X-Api-Key'):
            return None
        start = time.time()
        try:
            return fn(*args, **kwargs)
        finally:
            print(fn.__name__, 'took', time.time() - start)
    return wrapper

@audited
def get_user(uid):
    return db.find(uid)

@audited
def delete_user(uid):
    db.delete(uid)

What changed: auth and timing became one decorator; the functions contain only their own business logic.

