Refactor this code by modeling the operations as Command objects with undo:

class Editor:
    def apply(self, op, args):
        if op == 'insert':
            self.text = self.text[:args[0]] + args[1] + self.text[args[0]:]
            self.history.append(('insert', args))
        elif op == 'delete':
            start, length = args
            removed = self.text[start:start + length]
            self.text = self.text[:start] + self.text[start + length:]
            self.history.append(('delete', (start, removed)))

    def undo(self):
        op, args = self.history.pop()
        if op == 'insert':
            start, text = args
            self.text = self.text[:start] + self.text[start + len(text):]
        elif op == 'delete':
            start, removed = args
            self.text = self.text[:start] + removed + self.text[start:]

output:
from dataclasses import dataclass, field
from typing import List

@dataclass
class Insert:
    at: int
    text: str
    def execute(self, doc): doc.text = doc.text[:self.at] + self.text + doc.text[self.at:]
    def undo(self, doc): doc.text = doc.text[:self.at] + doc.text[self.at + len(self.text):]

@dataclass
class Delete:
    at: int
    length: int
    removed: str = ''
    def execute(self, doc):
        self.removed = doc.text[self.at:self.at + self.length]
        doc.text = doc.text[:self.at] + doc.text[self.at + self.length:]
    def undo(self, doc): doc.text = doc.text[:self.at] + self.removed + doc.text[self.at:]

@dataclass
class Document:
    text: str = ''
    history: List = field(default_factory=list)
    def run(self, command):
        command.execute(self)
        self.history.append(command)
    def undo(self):
        self.history.pop().undo(self)

What changed: op-strings became Command objects that know how to execute and undo themselves; adding 'replace' no longer edits two branches.

