Refactor this code by extracting State objects from the status if/elif chain:

def advance(ticket):
    if ticket['status'] == 'new':
        ticket['status'] = 'open'
        assign(ticket)
    elif ticket['status'] == 'open':
        if ticket['assignee']:
            ticket['status'] = 'pending'
        else:
            assign(ticket)
    elif ticket['status'] == 'pending':
        ticket['status'] = 'resolved'
        notify(ticket)
    elif ticket['status'] == 'resolved':
        ticket['status'] = 'closed'
        archive(ticket)

output:
class New:
    def advance(self, ticket):
        assign(ticket)
        return Open()

class Open:
    def advance(self, ticket):
        if not ticket['assignee']:
            assign(ticket)
            return self
        return Pending()

class Pending:
    def advance(self, ticket):
        notify(ticket)
        return Resolved()

class Resolved:
    def advance(self, ticket):
        archive(ticket)
        return Closed()

class Closed:
    def advance(self, ticket):
        return self

def advance(ticket):
    ticket['state'] = ticket['state'].advance(ticket)
    ticket['status'] = type(ticket['state']).__name__.lower()

What changed: each status is a State with its own transition; illegal moves and new statuses are added per class instead of editing a central chain.

