class LegacyClient:
    def do_GET(self, path, headers, body):
        if body:
            return 200, json.dumps(body).encode()
        return 200, b'{}'

class Service:
    def get(self, path):
        status, raw = LegacyClient().do_GET(path, {}, None)
        if status != 200:
            raise RuntimeError('bad status')
        return json.loads(raw)

output:
import json

class HttpClient:
    def get(self, path) -> dict: ...
    def post(self, path, payload) -> dict: ...

class LegacyAdapter(HttpClient):
    def __init__(self):
        self.legacy = LegacyClient()
    def get(self, path):
        status, raw = self.legacy.do_GET(path, {}, None)
        if status != 200:
            raise RuntimeError(f'bad status {status}')
        return json.loads(raw)

class Service:
    def __init__(self, client: HttpClient):
        self.client = client
    def get(self, path):
        return self.client.get(path)

What changed: the legacy signature is wrapped behind the modern HttpClient interface; Service now depends on the interface and can take a test double.

