output:
from abc import ABC, abstractmethod

class CleanJob(ABC):
    def run(self):
        rows = self.read()
        cleaned = [{k: v.strip() for k, v in r.items()} for r in rows if r.get('active')]
        self.write(cleaned)
    @abstractmethod
    def read(self): ...
    @abstractmethod
    def write(self, rows): ...

class CsvJob(CleanJob):
    def read(self): return list(csv.DictReader(open('in.csv')))
    def write(self, rows): json.dump(rows, open('out.json', 'w'))

class JsonJob(CleanJob):
    def read(self): return json.load(open('in.json'))
    def write(self, rows): json.dump(rows, open('out.json', 'w'))

What changed: run() defines the algorithm once in the base class; subclasses only override the read/write hooks.

