Refactor this code by making the handler chain a list of middleware instead of nested calls:

def handle(req):
    if not req.get('token'):
        return 401, 'unauthorized'
    if req['path'].startswith('/admin') and not req.get('admin'):
        return 403, 'forbidden'
    try:
        body = dispatch(req)
    except KeyError as e:
        return 404, f'missing {e}'
    return 200, body

output:
def require_token(req, nxt):
    if not req.get('token'):
        return 401, 'unauthorized'
    return nxt(req)

def require_admin(req, nxt):
    if req['path'].startswith('/admin') and not req.get('admin'):
        return 403, 'forbidden'
    return nxt(req)

def catch_missing(req, nxt):
    try:
        return nxt(req)
    except KeyError as e:
        return 404, f'missing {e}'

def handle(req):
    chain = [require_token, require_admin, catch_missing]
    def terminal(r):
        return 200, dispatch(r)
    nxt = terminal
    for mw in reversed(chain):
        nxt = lambda r, mw=mw, n=nxt: mw(r, n)
    return nxt(req)

What changed: nested inline checks became a chain-of-responsibility middleware list; reordering checks is now a list edit.

