Refactor this code by making the nested container render with a Composite:

def render(node):
    if node['type'] == 'text':
        return node['value']
    elif node['type'] == 'bold':
        return '<b>' + render(node['child']) + '</b>'
    elif node['type'] == 'para':
        return '<p>' + ''.join(render(c) for c in node['children']) + '</p>'
    elif node['type'] == 'section':
        return '<h2>' + node['title'] + '</h2>' + ''.join(render(c) for c in node['children'])
    return ''

output:
class Text:
    def __init__(self, value): self.value = value
    def render(self): return self.value

class Bold:
    def __init__(self, child): self.child = child
    def render(self): return f'<b>{self.child.render()}</b>'

class Para:
    def __init__(self, children): self.children = children
    def render(self): return '<p>' + ''.join(c.render() for c in self.children) + '</p>'

class Section:
    def __init__(self, title, children): self.title, self.children = title, children
    def render(self): return f'<h2>{self.title}</h2>' + ''.join(c.render() for c in self.children)

# document.render() works at any nesting depth without a central type switch

What changed: the type-dispatch function became node classes implementing render(); new node kinds no longer edit a central elif chain.

