def glyph(ch, size):
    return {'ch': ch, 'size': size, 'metrics': measure(ch, size), 'bitmap': rasterize(ch, size)}

text = [glyph(c, 12) for c in 'hello world hello world']

output:
_registry = {}

def glyph(ch, size):
    key = (ch, size)
    if key not in _registry:
        _registry[key] = {'ch': ch, 'size': size, 'metrics': measure(ch, size), 'bitmap': rasterize(ch, size)}
    return _registry[key]

text = [glyph(c, 12) for c in 'hello world hello world']
# 'hello' now shares one glyph object per character instead of allocating 24

What changed: immutable per-character data is interned in a registry (flyweight); repeated characters share one instance, cutting rasterization and memory.

