Refactor this code by turning the validator sequence into a chain of small validators:

def validate(payload):
    errors = []
    if 'email' not in payload:
        errors.append('email required')
    elif '@' not in payload['email']:
        errors.append('email invalid')
    if 'age' in payload and payload['age'] < 0:
        errors.append('age negative')
    if 'password' in payload and len(payload['password']) < 8:
        errors.append('password too short')
    if errors:
        raise ValidationError(errors)
    return payload

output:
class Validator:
    def __init__(self):
        self.next = None
        return self
    def then(self, other):
        self.next = other
        return other
    def check(self, payload):
        errors = self.validate(payload)
        if self.next:
            errors += self.next.check(payload)
        return errors
    def validate(self, payload): return []

class EmailValidator(Validator):
    def validate(self, payload):
        if 'email' not in payload: return ['email required']
        if '@' not in payload['email']: return ['email invalid']
        return []

class AgeValidator(Validator):
    def validate(self, payload):
        return ['age negative'] if payload.get('age', 0) < 0 else []

chain = EmailValidator().then(AgeValidator())
errors = chain.check(payload)
if errors:
    raise ValidationError(errors)

What changed: one method with three unrelated rules became composable validators; rules can be reordered or reused per endpoint.

class PublishingService:
